effect.frag.content:
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
float randomValue(vec2 p) { return float(hash(uint(p.x) + hash(uint(p.y) + uint(u_seed) * 31u + 17u)) >> 8) / 16777216.0; }
void main() {
  vec2 uv = v_uv * 16.0;
  float column = floor(uv.x), offset = randomValue(vec2(column, 0.0));
  vec2 cell = vec2(fract(uv.x + sin(TAU * u_progress + column) * 0.15), fract(uv.y + u_progress * 4.0 + offset));
  float flake = 1.0 - smoothstep(0.05, 0.13, length(cell - 0.5));
  vec4 c = sourceAt(v_uv);
  c.rgb = mix(c.rgb, vec3(c.a), flake * u_amount);
  fragColor = c;
}
